<?php require __DIR__.'/config.php';require_login();$cart=$_SESSION['cart']??[];if(!$cart)go('cart.php');$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks) AND status='active'");$s->execute($ids);$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=$p['price']*(int)$cart[$p['id']];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if($name===''||$phone===''||$address==='')$error='Please complete all delivery details.';else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO orders(user_id,total,status,customer_name,phone,address,payment_method) VALUES(?,?, 'Placed',?,?,?,?)");$s->execute([current_user()['id'],$total,$name,$phone,$address,'Cash on Delivery']);$oid=(int)$pdo->lastInsertId();$line=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)");foreach($items as $p){$qty=(int)$cart[$p['id']];if($qty>$p['stock'])throw new Exception('Stock changed for '.$p['name']);$line->execute([$oid,$p['id'],$p['name'],$p['price'],$qty]);$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=?")->execute([$qty,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);go('orders.php?placed=1');}catch(Throwable $e){$pdo->rollBack();$error='Order could not be placed: '.h($e->getMessage());}}}$pageTitle='Checkout';require __DIR__.'/includes/header.php';?><h1 class="page-title">Delivery details</h1><div class="cart-layout"><form class="checkout-form" method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><?php if($error): ?><div class="notice"><?= h($error) ?></div><?php endif; ?><label>Full name</label><input name="name" value="<?= h(current_user()['name']) ?>" required><label>Phone number</label><input name="phone" required><label>Delivery address</label><textarea name="address" rows="4" required></textarea><label>Payment method</label><div class="payment">Cash on Delivery</div><button class="btn full">Place order · <?= money($total) ?></button><p class="small-note">Demo checkout: no online payment is collected.</p></form><aside class="summary"><h3>Order total</h3><p><span>Items</span><b><?= array_sum($cart) ?></b></p><p><span>Delivery</span><b>Free</b></p><hr><p class="total"><span>Total</span><b><?= money($total) ?></b></p></aside></div><?php require __DIR__.'/includes/footer.php';?>
